// spec: specs/contact-login-return.md (3.1, 3.2) · кейсы: .qa/tests/contact-login-return/CONTACT-AUTH-08.md, CONTACT-AUTH-09.md
// seed: tests/seed.spec.ts (гость) · прод. «שלח הודעה» у гостя не делает ни одного не-GET запроса (проверено 27.10),
// плюс все не-GET запросы отклоняются (только Chromium → @desktop / @android). Вход не выполняется.
import { test, expect } from '@playwright/test';
import {
  prepareReadOnly, contactForm, fillQaFields, readDraft, readRedirectAfterLogin,
  DISCREET_ID, DISCREET_URL, QA_FIELDS, LOAD,
} from './contact-draft.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Форма «יצירת קשר עם המוכר» — возврат в форму после входа', () => {
  for (const device of ['@desktop', '@android']) {
    test(`Дискретное объявление: гость отправляет форму → черновик сохранён → /auth с возвратом на объявление #3f0a85 ${device} @prod-safe`, async ({ page }) => {
      await prepareReadOnly(page);
      await page.goto(DISCREET_URL);

      await page.getByRole('button', { name: 'שלח הודעה למוכר' }).first().click({ timeout: LOAD.timeout });
      const form = contactForm(page);
      await expect(form, 'открылась форма «יצירת קשר עם המוכר»').toBeVisible(LOAD);
      await fillQaFields(form);
      const startedAt = Date.now();

      await form.getByRole('button', { name: 'שלח הודעה' }).click();

      await expect(form.getByText('עליך להתחבר כדי לשלוח הודעה.'), 'сообщение «нужно войти»').toBeVisible();
      await page.waitForURL((u) => u.pathname === '/auth', LOAD);
      await expect(page.getByText('על מנת להתעניין בעסקים'), '/auth показывает текст намерения (#6ce2cc)').toBeVisible(LOAD);

      const draft = await readDraft(page);
      expect(draft, 'черновик b4s_contact_draft записан').not.toBeNull();
      expect(draft!.businessId, 'черновик — этого объявления').toBe(DISCREET_ID);
      expect(draft!.fields.message, 'в черновике — введённое сообщение').toBe(QA_FIELDS.message);
      expect(draft!.at, 'время черновика — сейчас').toBeGreaterThanOrEqual(startedAt - 5_000);

      const saved = await readRedirectAfterLogin(page);
      expect(saved, 'redirectAfterLogin записан').not.toBeNull();
      const target = new URL(saved!, 'https://x');
      expect(target.pathname, 'возврат — на страницу объявления').toBe('/businessdetail');
      expect(target.searchParams.get('id'), 'возврат — на это же объявление').toBe(DISCREET_ID);
    });
  }

  test('Выдача /search: «השארת פרטים» → та же форма → гостевая отправка возвращает на объявление этой карточки #3f0a85 @android @prod-safe', async ({ page }) => {
    await prepareReadOnly(page);
    await page.goto('/search');

    const leaveBtn = page.getByRole('button', { name: 'השארת פרטים' }).first();
    // выдача на проде под нагрузкой грузится и перестраивается 10–20 с
    await expect(leaveBtn).toBeVisible({ timeout: 30_000 });
    await leaveBtn.scrollIntoViewIfNeeded();
    // id объявления карточки — из ближайшей ссылки на /businessdetail в карточке кнопки
    const cardHref = await leaveBtn.evaluate((el) => {
      let c: HTMLElement | null = el as HTMLElement;
      for (let i = 0; i < 12 && c; i++) {
        c = c.parentElement;
        const a = c?.querySelector('a[href*="businessdetail"]');
        if (a) return a.getAttribute('href');
      }
      return null;
    });
    expect(cardHref, 'у карточки есть ссылка на объявление').not.toBeNull();
    const cardId = new URL(cardHref!, 'https://x').searchParams.get('id');
    expect(cardId).toBeTruthy();

    await leaveBtn.click();
    const form = contactForm(page);
    await expect(form, 'открылась форма «יצירת קשר עם המוכר»').toBeVisible(LOAD);
    await fillQaFields(form);
    await form.getByRole('button', { name: 'שלח הודעה' }).click();

    await page.waitForURL((u) => u.pathname === '/auth', LOAD);
    const draft = await readDraft(page);
    expect(draft?.businessId, 'черновик — объявления этой карточки').toBe(cardId);
    const saved = await readRedirectAfterLogin(page);
    expect(saved, 'redirectAfterLogin записан').not.toBeNull();
    const target = new URL(saved!, 'https://x');
    expect(target.pathname, 'возврат — на страницу объявления').toBe('/businessdetail');
    expect(target.searchParams.get('id'), 'возврат — на объявление этой карточки').toBe(cardId);
  });
});
